import{_ as a,o as t,c as n,a3 as i}from"./chunks/framework.DhF4LrUq.js";const g=JSON.parse('{"title":"Tenancy and isolation","description":"","frontmatter":{},"headers":[],"relativePath":"concepts/tenancy-isolation.md","filePath":"concepts/tenancy-isolation.md"}'),o={name:"concepts/tenancy-isolation.md"};function s(r,e,l,c,d,h){return t(),n("div",null,[...e[0]||(e[0]=[i(`<h1 id="tenancy-and-isolation" tabindex="-1">Tenancy and isolation <a class="header-anchor" href="#tenancy-and-isolation" aria-label="Permalink to &quot;Tenancy and isolation&quot;">​</a></h1><p>ShipperDog is built for enterprises that distribute apps to many internal or customer populations at once. The tenancy model keeps each population&#39;s data separate while letting one organization govern everything centrally.</p><h2 id="the-hierarchy" tabindex="-1">The hierarchy <a class="header-anchor" href="#the-hierarchy" aria-label="Permalink to &quot;The hierarchy&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Organization</span></span>
<span class="line"><span>├── Users (members with roles)</span></span>
<span class="line"><span>├── Tenants</span></span>
<span class="line"><span>│   ├── Members and testers</span></span>
<span class="line"><span>│   ├── Tester groups</span></span>
<span class="line"><span>│   └── Applications (tenant-owned)</span></span>
<span class="line"><span>├── Applications (organization-shared, optional)</span></span>
<span class="line"><span>├── Policies, rings, approval workflows</span></span>
<span class="line"><span>└── Audit logs</span></span></code></pre></div><ul><li><strong>Organization</strong> — the top-level enterprise account. Platform administrators create organizations; the creator becomes its first organization administrator. Members hold organization roles (<code>ORG_ADMIN</code>, <code>APP_OWNER</code>, <code>DEVELOPER</code>, <code>QA_ENGINEER</code>, <code>RELEASE_MANAGER</code>, <code>SECURITY_REVIEWER</code>, <code>COMPLIANCE_REVIEWER</code>, <code>VIEWER</code>, and plain <code>ORG_MEMBER</code>).</li><li><strong>Tenant</strong> — a customer or business entity inside the organization: &quot;Acme Bank&quot;, &quot;Contoso&quot;. Every tenant belongs to exactly one organization. A tenant is never a user — it has no login. Tenant identifiers are unique within the organization (name) and globally (external id, your billing/CRM mapping).</li><li><strong>Application</strong> — belongs to a tenant, or is shared at the organization level. See below.</li><li><strong>Testers</strong> — real people who install builds. A tester record belongs to the organization and is linked to tenants through memberships; testers do not need to be organization members.</li></ul><h2 id="tenant-owned-and-organization-shared-applications" tabindex="-1">Tenant-owned and organization-shared applications <a class="header-anchor" href="#tenant-owned-and-organization-shared-applications" aria-label="Permalink to &quot;Tenant-owned and organization-shared applications&quot;">​</a></h2><p>An application has exactly one of two ownership scopes:</p><ul><li><strong>Tenant-owned</strong> — one owning tenant manages it. Other tenants see it only when explicitly authorized.</li><li><strong>Organization-shared</strong> — the organization itself owns it (think: one corporate app every customer tenant receives). Which tenants can see it is managed through an explicit authorization mapping: grant with a reason, revoke the same way, everything audited.</li></ul><p>Shared visibility is always opt-in and never ambient. Before a grant, a tenant&#39;s application list is exactly its own rows. The scope can be converted later, but not while releases target the application — distribution history anchors it.</p><h2 id="who-can-do-what" tabindex="-1">Who can do what <a class="header-anchor" href="#who-can-do-what" aria-label="Permalink to &quot;Who can do what&quot;">​</a></h2><p>Effective permissions are the union of every role a person holds across organization and tenant scopes:</p><ul><li>Organization roles apply organization-wide. An <code>ORG_ADMIN</code> reaches into every tenant of their organization.</li><li>Tenant roles (<code>TENANT_ADMIN</code>, <code>TENANT_TESTER</code>) apply inside one tenant. Tenant testers — the tester persona — hold no other role at all: their access is membership plus explicit version grants.</li><li>Membership alone grants nothing (<code>ORG_MEMBER</code> is deny-by-default). A fresh member can do nothing until granted a functional role.</li></ul><p>Memberships carry their own status besides the account status: both switches must be on. Suspending a membership takes effect on the very next request — roles are evaluated live from the database on every call, never baked into tokens.</p><h2 id="isolation-two-layers-by-construction" tabindex="-1">Isolation: two layers, by construction <a class="header-anchor" href="#isolation-two-layers-by-construction" aria-label="Permalink to &quot;Isolation: two layers, by construction&quot;">​</a></h2><p>Tenant isolation is not a convention the API tries to remember. It is enforced twice:</p><ol><li><strong>At the endpoint.</strong> Every tenant-scoped route checks the caller&#39;s standing. A caller without a role in the tenant (or its owning organization) receives the same <code>404</code> as if the tenant did not exist — a denied caller cannot distinguish &quot;not yours&quot; from &quot;not there&quot;.</li><li><strong>At the data layer.</strong> Every tenant-scoped database query composes a tenant filter by construction. A query that would span tenants fails closed instead of running. Architecture tests reject any code path that bypasses the isolation layer.</li></ol><p>Platform administrators can operate across tenants for break-glass operations, and every such request records an explicit, audited cross-tenant access event. Organization roles can never take that path.</p><h2 id="deactivation-is-reversible-and-non-destructive" tabindex="-1">Deactivation is reversible and non-destructive <a class="header-anchor" href="#deactivation-is-reversible-and-non-destructive" aria-label="Permalink to &quot;Deactivation is reversible and non-destructive&quot;">​</a></h2><ul><li>A <strong>deactivated tenant</strong> blocks new memberships and affiliations but preserves everything: members, applications, and data remain readable and administrable so the tenant can be inspected and reactivated.</li><li>A <strong>deactivated organization</strong> keeps its memberships but they grant nothing; members whose organizations are all deactivated cannot sign in (platform administrators are exempt — that is the break-glass path).</li></ul><h2 id="ring-visibility" tabindex="-1">Ring visibility <a class="header-anchor" href="#ring-visibility" aria-label="Permalink to &quot;Ring visibility&quot;">​</a></h2><p>Tenants also interact with rollout rings: at a given ring, the tenants a release targets are intersected with the ring&#39;s eligibility rules, so widening a release stage by stage can admit tenant populations progressively. See <a href="/shipperdog/snapshot/concepts/rings-and-rollout">rings and rollout</a>.</p><h2 id="where-to-go-deeper" tabindex="-1">Where to go deeper <a class="header-anchor" href="#where-to-go-deeper" aria-label="Permalink to &quot;Where to go deeper&quot;">​</a></h2><ul><li><a href="/shipperdog/snapshot/concepts/authorization">Authorization</a> — the seven-layer decision chain and the grant shapes that admit testers</li><li><a href="/shipperdog/snapshot/concepts/security-model">Security model</a> — the audit trail and the fail-closed posture behind isolation</li><li>Developer detail: the <a href="https://github.com/ShristiLabs/shipperdog/blob/main/docs/tenants.md" target="_blank" rel="noreferrer">tenants</a>, <a href="https://github.com/ShristiLabs/shipperdog/blob/main/docs/organizations.md" target="_blank" rel="noreferrer">organizations</a>, and <a href="https://github.com/ShristiLabs/shipperdog/blob/main/docs/authorization.md" target="_blank" rel="noreferrer">authorization</a> module docs.</li></ul>`,23)])])}const u=a(o,[["render",s]]);export{g as __pageData,u as default};
